CREATE TABLE documents (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, purchase_id uuid REFERENCES purchases ON DELETE CASCADE, return_id uuid REFERENCES returns ON DELETE CASCADE, purpose text NOT NULL CHECK(purpose IN ('receipt','label','evidence')), content_type text NOT NULL CHECK(content_type IN ('application/pdf','image/jpeg','image/png')), byte_length bigint NOT NULL CHECK(byte_length BETWEEN 1 AND 8388608), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','ready')), created_at timestamptz NOT NULL DEFAULT now(), CHECK((purchase_id IS NOT NULL)::integer+(return_id IS NOT NULL)::integer=1));
CREATE INDEX documents_owner ON documents(user_id);
CREATE TABLE object_deletions (object_key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION queue_deleted_document() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO object_deletions(object_key) VALUES ('documents/'||OLD.id::text),('staging/'||OLD.id::text) ON CONFLICT DO NOTHING; RETURN OLD; END $$;
CREATE TRIGGER document_deleted AFTER DELETE ON documents FOR EACH ROW EXECUTE FUNCTION queue_deleted_document();
